using System;using System.IO;using System.Reflection;using System.Collections.Generic;using Microsoft.Build.Evaluation;using Microsoft.Build.Execution;using Microsoft.Build.Framework;using Microsoft.Build.Logging;
namespace FFW.NativeBuild3 {
public static class Launcher { public static string Build(string assemblyPath,string buildDir,string project,string vs,string log) { var setup=new AppDomainSetup { ApplicationBase=buildDir,ConfigurationFile=Path.Combine(buildDir,"MSBuild.exe.config") };var domain=AppDomain.CreateDomain("FFW isolated native build",null,setup);try {var worker=(Worker)domain.CreateInstanceFromAndUnwrap(assemblyPath,typeof(Worker).FullName);return worker.Run(buildDir,project,vs,log);}finally{AppDomain.Unload(domain);}}}
public class Worker:MarshalByRefObject { public string Run(string dir,string project,string vs,string log) { AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{var p=Path.Combine(dir,new AssemblyName(e.Name).Name+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};return BuildProject(dir,project,vs,log); }
[System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)] private string BuildProject(string dir,string project,string vs,string log) { var props=new Dictionary<string,string>{{"Configuration","Release"},{"Platform","x64"},{"VCTargetsPath",Path.Combine(vs,"MSBuild/Microsoft/VC/v170/")},{"VisualStudioVersion","17.0"},{"VSInstallDir",vs+"/"},{"VCInstallDir",vs+"/VC/"}};using(var pc=new ProjectCollection(props)){pc.AddToolset(new Toolset("Current",dir,pc,""));var parameters=new BuildParameters(pc){MaxNodeCount=1,EnableNodeReuse=false,Loggers=new ILogger[]{new FileLogger { Parameters="logfile="+log,Verbosity=LoggerVerbosity.Normal }}};using(var manager=new BuildManager("FFW native API")){var result=manager.Build(parameters,new BuildRequestData(project,props,"Current",new[]{"Build"},null));return result.OverallResult.ToString()+(result.Exception==null?"":"\n"+result.Exception);}}}
public override object InitializeLifetimeService(){return null;}
}}
